    /// <summary>
    /// Validate write for METCBCTInvoiceHeaderTable table record
    /// </summary>
    /// <returns>true if record is valid for write, otherwise false</returns>
    public boolean validateWrite()
    {
        boolean ret;

        if (!this.Number)
        {
            this.Number = NumberSeq::newGetNum(VendParameters::METnumRefCBCTNumber()).num();
        }

        ret = super();

        return ret;
    }

/// <summary>
/// CustTable associated with CustomerAccount field
/// </summary>
/// <returns>CustTable record if found, null otherwise</returns>
public CustTable custTable()
{
    CustTable   custTable;
    custTable   = CustTable::find(this.CustomerAccount);
    return custTable;
}

/// <summary>
/// VenTable record associated with VendorAccount field
/// </summary>
/// <returns>VendTable record if found, null otherwise</returns>
public VendTable vendTable()
{
    return VendTable::find(this.VendorAccount);
}

/// <summary>
/// Set default value on the table fields
/// </summary>
public void initValue()
{
    this.CurrencyCode = Ledger::accountingCurrency(CompanyInfo::current());
    this.TransactionDate =  DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
    super();
}

    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(METCBCTInvoiceHeaderTable, CustomerAccount):
            case fieldNum(METCBCTInvoiceHeaderTable, VendorAccount):
                this.assignFinancialDimension();
                this.setTermsOfPayments();
                this.setDueDates();
                this.setCashDiscFields();
                break;
            case fieldNum(METCBCTInvoiceHeaderTable,CustPaymTermId):
            case fieldNum(METCBCTInvoiceHeaderTable,VendPaymTermId):
                this.setDueDates();
                break;

        }
    }

/// <summary>
/// Set financial dimension on the line.
/// </summary>
private void assignFinancialDimension()
{
    CustTable       custTable = CustTable::find(this.CustomerAccount);
    VendTable       vendTable = VendTable::find(this.VendorAccount);
    if (custTable.RecId && vendTable.RecId)
    {
        this.FinancialDimension = DimensionDefaultFacade::serviceMergeDefaultDimensions(vendTable.DefaultDimension,custTable.DefaultDimension);
        //Merge profit center dimension from the "Charge Through Customer Profit Centre link" table
        DimensionValue profitCentreValue = this.defaultProfitCentre();
        if (profitCentreValue)
        {
            this.setProfitCentre(this.FinancialDimension,'ProfitCentre',profitCentreValue);
        }
    }
    else if (custTable.RecId)
    {
        this.FinancialDimension = custTable.DefaultDimension;
    }
   
}

    /// <summary>
    /// Set terms of payment
    /// </summary>
    public void setTermsOfPayments()
    {
        /*
        Steps to determine terms of payments
        1. Find customer classification
        2. Find vendor classification
        3. Find term classification based on combination of customer and vendor classification from "METCBCTCustomerProfitCentreLink" table
        4. Find matching record of term classification + vendor in "Charge through vendor payment link" table
        5. Default customer and payment termID based on the matched record
        6. If no matching record found in "Charge through vendor payment link" table then default from customer and vendor master table
        */
        if (this.CustomerAccount && this.VendorAccount)
        {
            METCBCTClassificationID                 custClassificationID = METCustTable::find(this.CustomerAccount).CBCTClassificationID;
            METCBCTClassificationID                 vendClassificationID = METVendTable::find(this.VendorAccount).CBCTClassificationID;
            METCBCTChargethroughVendorPaymentLink   chargethroughVendorPaymentLink;
            METCBCTCustomerProfitCentreLink         customerProfitCentreLink;

            select firstonly chargethroughVendorPaymentLink
                where chargethroughVendorPaymentLink.VendAccount == this.VendorAccount
                join customerProfitCentreLink
                 where customerProfitCentreLink.TermClassificationID == chargethroughVendorPaymentLink.TermClassificationID
                && customerProfitCentreLink.CustClassificationID == custClassificationID
                && customerProfitCentreLink.VendClassificationID == vendClassificationID
                && customerProfitCentreLink.TermClassificationID;

            this.CustPaymTermId = chargethroughVendorPaymentLink.CustPaymTermId ? chargethroughVendorPaymentLink.CustPaymTermId : CustTable::find(this.CustomerAccount).PaymTermId;
            this.VendPaymTermId = chargethroughVendorPaymentLink.VendPaymTermId ? chargethroughVendorPaymentLink.VendPaymTermId : VendTable::find(this.VendorAccount).PaymTermId;
        }
    }

    /// <summary>
    /// Set settlement discount fields
    /// </summary>
    public void setCashDiscFields()
    {
        /*
        Steps to determine terms of payments
        1. Find customer classification
        2. Find vendor classification
        3. Find term classification based on combination of customer and vendor classification from "METCBCTCustomerProfitCentreLink" table
        4. Find matching record of term classification + vendor in "Charge through vendor payment link" table for the latest from date based on document date
        5. Default customer and payment termID based on the matched record
        6. If no matching record found in "Charge through vendor payment link" table then default from customer and vendor master table
        */
        if (this.CustomerAccount && this.VendorAccount)
        {
            METCBCTClassificationID                 custClassificationID = METCustTable::find(this.CustomerAccount).CBCTClassificationID;
            METCBCTClassificationID                 vendClassificationID = METVendTable::find(this.VendorAccount).CBCTClassificationID;
            METCBCTChargethroughVendorPaymentLink   chargethroughVendorPaymentLink;
            METCBCTCustomerProfitCentreLink         customerProfitCentreLink;

            select firstonly chargethroughVendorPaymentLink order by FromDate Desc
                where chargethroughVendorPaymentLink.VendAccount == this.VendorAccount
                    && chargethroughVendorPaymentLink.FromDate <= this.DocumentDate
                    && chargethroughVendorPaymentLink.ToDate >= this.DocumentDate
                join customerProfitCentreLink
                    where customerProfitCentreLink.TermClassificationID == chargethroughVendorPaymentLink.TermClassificationID
                    && customerProfitCentreLink.CustClassificationID == custClassificationID
                    && customerProfitCentreLink.VendClassificationID == vendClassificationID
                    && customerProfitCentreLink.TermClassificationID;

            this.CustCashDisc = chargethroughVendorPaymentLink.CustCashDisc ? chargethroughVendorPaymentLink.CustCashDisc : CustTable::find(this.CustomerAccount).CashDisc;
            this.VendCashDisc = chargethroughVendorPaymentLink.VendCashDisc ?  chargethroughVendorPaymentLink.VendCashDisc : VendTable::find(this.VendorAccount).CashDisc;
        }
    }

/// <summary>
/// MPJ_37288_ChargebackChargethrough_extension functionalities(MPJ_3587)
/// Set due dates
/// </summary>
public void setDueDates()
{
    METCBCTParameters   metCBCTParameters = METCBCTParameters::Find();
    if(metCBCTParameters)
    {
    
        if (this.CustPaymTermId)
        {
            switch(metCBCTParameters.CustDueDateBasis)
            {
                case METCBCTCustDueDateBasis::TransactionDate :
                    this.CustDueDate = PaymTerm::find(this.CustPaymTermId).due(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
                    break;
                case METCBCTCustDueDateBasis::VendorInvoiceDate :
                    this.CustDueDate = PaymTerm::find(this.CustPaymTermId).due(this.TransactionDate);
                    break;
            }
        
        }
        if (this.VendPaymTermId)
        {
            switch(metCBCTParameters.VendDueDateBasis)
            {
                case METCBCTVendDueDateBasis::TransactionDate :
                    this.VendDueDate = PaymTerm::find(this.VendPaymTermId).due(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
                    break;
                case METCBCTVendDueDateBasis::VendorInvoiceDate :
                    this.VendDueDate = PaymTerm::find(this.VendPaymTermId).due(this.TransactionDate);
                    break;
            }
            
        }
    }
}

    /// <summary>
    /// Set profit centre
    /// </summary>
    /// <param name = "_defaultDimension">
    /// Dimension default value
    /// </param>
    ///  <param name = "_dimensionName">
    /// Dimension name
    /// </param>
    ///  <param name = "_dimensionValue">
    /// Dimension value
    /// </param>
    public void setProfitCentre(DimensionDefault _defaultDimension,
                                Name             _dimensionName,
                                DimensionValue   _dimensionValue)
    {
        //'ProfitCentre'
        DimensionAttribute                  dimAttribute;
        DimensionAttributeValue             dimAttributeValue;
        DimensionAttributeValueSetStorage   dimStorage;

        dimStorage      = DimensionAttributeValueSetStorage::find(_defaultDimension);
        dimAttribute    = DimensionAttribute::findByName(_dimensionName);

        if (_dimensionValue)
        {
            dimAttributeValue = DimensionAttributeValue::findByDimensionAttributeAndValue(dimAttribute, _dimensionValue, true, true);
            dimStorage.addItem(dimAttributeValue);
        }
        else
        {
            dimStorage.removeDimensionAttribute(dimAttribute.RecId);
        }

        this.FinancialDimension = dimStorage.save();
    }

    /// <summary>
    /// Defaults profit center
    /// </summary>
    /// <returns>
    /// Dimension value
    /// </returns>
    public DimensionValue defaultProfitCentre()
    {
        DimensionValue                      profitCentreValue;
        METCBCTClassificationID             custClassificationID = METCustTable::find(this.CustomerAccount).CBCTClassificationID;
        METCBCTClassificationID             vendClassificationID = METVendTable::find(this.VendorAccount).CBCTClassificationID;
        METCBCTCustomerProfitCentreLink     customerProfitCentreLink =  METCBCTCustomerProfitCentreLink::find(custClassificationID,vendClassificationID);

        if (customerProfitCentreLink.recId)
        {
            profitCentreValue = customerProfitCentreLink.ProfitCentre;
        }
        else
        {
            //find from METCBCTCustomerSiteOffRemitProfitCentreLink table
            METCBCTCustomerSiteOffRemitProfitCentreLink     customerSiteOffRemitProfitCentreLink;
            InventSiteId                                    inventSiteId = CustTable::find(this.CustomerAccount).InventSiteId;

            select firstonly customerSiteOffRemitProfitCentreLink where customerSiteOffRemitProfitCentreLink.InventSiteId == inventSiteId;
            if (customerSiteOffRemitProfitCentreLink.RecId)
            {
                profitCentreValue = customerSiteOffRemitProfitCentreLink.ProfitCentre;
            }
        }
        return profitCentreValue;
    }

    /// <summary>
    /// Performs validation on fields
    /// </summary>
    /// <param name = "_fieldIdToCheck">
    /// Field ID for which the value need to be validated
    /// </param>
    /// <returns>
    /// Boolean value
    /// </returns>
    public boolean validateField(FieldId _fieldIdToCheck)
    {
        boolean ret;
    
        ret = super(_fieldIdToCheck);

        switch (_fieldIdToCheck)
        {
            case fieldNum(METCBCTInvoiceHeaderTable, VendorAccount):
                ret = ret && this.validateVendorAccount();
                break;
            case fieldNum(METCBCTInvoiceHeaderTable, CustomerAccount):
                ret = ret && this.validateCustomerAccount();
                break;
        }
        return ret;
    }

/// <summary>
/// Validates value of selected vendor account
/// </summary>
/// <returns>
/// True if the vendor is Charge through vendor
/// </returns>
public boolean validateVendorAccount()
{
    boolean ret;
    ret = METVendTable::find(this.VendorAccount).CBCT ? true : checkFailed("@MET:VendorNotPermittedForChargethrough");
    return ret;
}

/// <summary>
/// Validates value of selected customer account
/// </summary>
/// <returns>
/// True if the customer has signed up for the Charge through process
/// </returns>
public boolean validateCustomerAccount()
{
    boolean ret;
    ret = METCustTable::find(this.CustomerAccount).CBCTCustomer? true : checkFailed("@MET:CustomerNotValidForChargethrough");
    return ret;
}

/// <summary>
/// MPJ-31514
/// </summary>
public void insert()
{
    this.assignFinancialDimension();
    this.setTermsOfPayments();
    this.setDueDates();
    this.setCashDiscFields();
    this.setDueDates();
    super();
    //MPJ_37288_ChargebackChargethrough_extension (MPJ_3587)
    
    Args args = new Args(this);
    args.record(this);
    METCBCTInvoiceLinesCreation::main(args);
    
}
